		warnings = append(warnings, semanticWarning{Code: "default_branch_unknown", Severity: "warning", Effect: "freshness", Detail: warning})
	}
	if indexOpts.skipSem {
		header = semanticHeader{
			SchemaVersion: "1.0",
			Provider:      "skipped",
			RepoRoot:      repoDir,
			RepoKey:       storage.Key,
			Commit:        head,
			Tree:          tree,
