	cacheDir, err := resolveXDGDir(env.PluginCacheDir, envPluginCacheDir, xdgCacheHome, filepath.Join(".cache", xdgRootDir))
	if err != nil {
		return pluginDirs{}, fmt.Errorf("resolve plugin cache dir: %w", err)
